// SuckCParserInit initializes any static state used to implement SuckCParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewSuckCParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func SuckCParserInit() {
	staticData := &SuckCParserParserStaticData
	staticData.once.Do(suckcparserParserInit)
}

// NewSuckCParser produces a new parser instance for the optional input antlr.TokenStream.
func NewSuckCParser(input antlr.TokenStream) *SuckCParser {
	SuckCParserInit()
	this := new(SuckCParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &SuckCParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "SuckCParser.g4"

	return this
}

